changeSet.sql:
ALTER TABLE modeling_model_release_candidate DROP CONSTRAINT ck_model_release_candidate_status; ALTER TABLE modeling_model_release_candidate_entry DROP CONSTRAINT ck_model_release_candidate_entry_status; ALTER TABLE modeling_model_release_candidate_entry DROP CONSTRAINT ck_model_release_candidate_entry_build_snapshot; ALTER TABLE modeling_model_release_candidate_command DROP CONSTRAINT ck_model_release_candidate_command_payload; DROP INDEX uk_model_release_candidate_active_plan;
ALTER TABLE modeling_model_release_candidate ADD CONSTRAINT ck_model_release_candidate_status CHECK ( status IN ( 'DRAFT', 'BUILDING', 'BUILD_FAILED', 'BUILT', 'QUALITY_RUNNING', 'QUALITY_FAILED', 'QUALITY_PASSED', 'REVIEW_PENDING', 'REJECTED', 'APPROVED', 'PUBLISHING', 'PARTIAL', 'PUBLISHED', 'ROLLED_BACK', 'CANCELLED', 'STALE' ) ); ALTER TABLE modeling_model_release_candidate_entry ADD CONSTRAINT ck_model_release_candidate_entry_status CHECK ( status IN ( 'DRAFT', 'BUILDING', 'BUILD_FAILED', 'BUILT', 'QUALITY_RUNNING', 'QUALITY_FAILED', 'QUALITY_PASSED', 'REVIEW_PENDING', 'REJECTED', 'APPROVED', 'PUBLISHING', 'PARTIAL', 'PUBLISHED', 'ROLLED_BACK', 'CANCELLED', 'STALE' ) ); ALTER TABLE modeling_model_release_candidate_entry ADD CONSTRAINT ck_model_release_candidate_entry_build_snapshot CHECK ( ( implementation_revision IS NULL AND implementation_checksum IS NULL AND dbt_unique_id IS NULL AND target_identifier IS NULL AND artifact_bundle_checksum IS NULL AND dependency_snapshot_checksum IS NULL AND active_claim_key IS NULL ) OR ( implementation_id IS NOT NULL AND implementation_revision > 0 AND implementation_checksum ~ '^[0-9a-f]{64}$' AND dbt_unique_id ~ '^model\.[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*$' AND target_identifier ~ '^[A-Za-z_][A-Za-z0-9_]*$' AND artifact_bundle_checksum ~ '^[0-9a-f]{64}$' AND dependency_snapshot_checksum ~ '^[0-9a-f]{64}$' AND ( (status = 'CANCELLED' AND active_claim_key IS NULL) OR ( status <> 'CANCELLED' AND active_claim_key ~ '^[0-9a-f]{64}$' ) ) ) ); ALTER TABLE modeling_model_release_candidate_command ADD CONSTRAINT ck_model_release_candidate_command_payload CHECK ( candidate_version > 0 AND event_type IN ('CREATED', 'SCOPE_REPLACED', 'STATUS_CHANGED', 'STALE_DETECTED') AND to_status IN ( 'DRAFT', 'BUILDING', 'BUILD_FAILED', 'BUILT', 'QUALITY_RUNNING', 'QUALITY_FAILED', 'QUALITY_PASSED', 'REVIEW_PENDING', 'REJECTED', 'APPROVED', 'PUBLISHING', 'PARTIAL', 'PUBLISHED', 'ROLLED_BACK', 'CANCELLED', 'STALE' ) AND ( from_status IS NULL OR from_status IN ( 'DRAFT', 'BUILDING', 'BUILD_FAILED', 'BUILT', 'QUALITY_RUNNING', 'QUALITY_FAILED', 'QUALITY_PASSED', 'REVIEW_PENDING', 'REJECTED', 'APPROVED', 'PUBLISHING', 'PARTIAL', 'PUBLISHED', 'ROLLED_BACK', 'CANCELLED', 'STALE' ) ) AND ((event_type = 'CREATED' AND from_status IS NULL) OR (event_type <> 'CREATED' AND from_status IS NOT NULL)) AND btrim(actor_id) <> '' AND actor_id = btrim(actor_id) AND btrim(reason) <> '' AND octet_length(reason) <= 4096 AND btrim(idempotency_key) <> '' AND idempotency_key = btrim(idempotency_key) AND request_hash ~ '^[0-9a-f]{64}$' AND jsonb_typeof(response_snapshot) = 'object' AND octet_length(response_snapshot::text) <= 1048576 );
CREATE UNIQUE INDEX uk_model_release_candidate_active_plan ON modeling_model_release_candidate (tenant_id, plan_id) WHERE status NOT IN ('REJECTED', 'ROLLED_BACK', 'STALE', 'CANCELLED');

rollback.sql:
DO $$ BEGIN LOCK TABLE modeling_model_release_candidate, modeling_model_release_candidate_entry, modeling_model_release_candidate_command IN ACCESS EXCLUSIVE MODE; IF EXISTS ( SELECT 1 FROM modeling_model_release_candidate WHERE status = 'CANCELLED' ) OR EXISTS ( SELECT 1 FROM modeling_model_release_candidate_entry WHERE status = 'CANCELLED' OR ( implementation_revision IS NOT NULL AND active_claim_key IS NULL ) ) THEN RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_RELEASE_CANDIDATE_CANCEL_DATA_EXISTS'; END IF;
